const r=["Production Date","Pending Order Quantity","Current Balance","Production In Progress","Maximum Allowed Production","Sample Item","Sample Item Qty","Last Item","Last Plan Qty","Deviation Allowed","Planned Quantity","Remarks","No. of Parts","UPS","Length","Breadth","Height","PLY","Flute","ID to OD","Take up Factor","GSM","Color 1","Color 2","Printing Color","L1","F1","L2","F2","L3","Reel Per Calc","No. of ups in Cutting (For Plates)","Reel Actual Trim","Cutting Trim","Sheet Weight","Plate/PHP Weight","Total Paper Wt","Total Wt of Set","Actual Paper Used","Rate","Realization/KG","Prod (Sheet Plant)","Prod (Meter)","Planned Prod (Mtr)","Least GSM","Flute Batches","Company Name"];function i(o){if(!o)return[...r];try{const e=JSON.parse(o);if(Array.isArray(e)){const a=e.filter(t=>t!=="Top").map(t=>t).filter(t=>typeof t=="string"&&r.includes(t));return a.length>0?a:[...r]}}catch(e){console.error("Failed to parse production form visible columns:",e)}return[...r]}export{r as P,i as p};
